      "type": "object",
      "properties": {
        "name": {
          "description": "The name of the vendor.",
          "type": "string"
        },
        "address": {
          "description": "The full address of the vendor.",
          "type": "string"
        },
        "email": {
          "description": "The email address of the vendor.",
          "type": "string"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
    "customer": {
      "description": "Information about the customer or the entity being billed.",
      "type": "object",
      "properties": {
        "name": {
          "description": "The name of the customer.",
          "type": "string"
        },
        "address": {
          "description": "The full billing address of the customer.",
          "type": "string"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
